// Generates the Dart and Swift token files from design/tokens.json.
//
// Usage: dart run tool/gen_tokens.dart [--check]
// With --check it exits 1 when a generated file is out of date.

import 'dart:convert';
import 'dart:io';

const _source = 'design/tokens.json';
const _dartOut = 'packages/due_kit/lib/src/foundation/tokens.g.dart';
const _swiftOut = 'app/ios/DueWidget/DueTokens.g.swift';
const _header = 'GENERATED by tool/gen_tokens.dart from design/tokens.json. Do not edit.';

void main(List<String> args) {
  final check = args.contains('--check');
  final tokens = jsonDecode(File(_source).readAsStringSync()) as Map<String, dynamic>;
  final outputs = {_dartOut: _dart(tokens), _swiftOut: _swift(tokens)};

  var stale = false;
  outputs.forEach((path, content) {
    final file = File(path);
    final current = file.existsSync() ? file.readAsStringSync() : null;
    if (current == content) return;
    if (check) {
      stderr.writeln('$path is out of date. Run `mise run gen`.');
      stale = true;
    } else {
      file.parent.createSync(recursive: true);
      file.writeAsStringSync(content);
      stdout.writeln('wrote $path');
    }
  });
  if (stale) exit(1);
}

/// Parses `#RRGGBB` or `#AARRGGBB` into a 32-bit ARGB value.
int _argb(String hex) {
  final h = hex.substring(1);
  if (h.length == 6) return 0xFF000000 | int.parse(h, radix: 16);
  if (h.length == 8) return int.parse(h, radix: 16);
  throw FormatException('Bad colour $hex');
}

String _hex(int v) => '0x${v.toRadixString(16).toUpperCase().padLeft(8, '0')}';

String _num(Object v) => v is int ? '$v' : '$v';

String _dart(Map<String, dynamic> t) {
  final color = t['color'] as Map<String, dynamic>;
  final light = (color['light'] as Map).cast<String, String>();
  final dark = (color['dark'] as Map).cast<String, String>();
  final names = light.keys.toList();
  if (!_sameKeys(light, dark)) throw StateError('light and dark colour keys differ');

  final b = StringBuffer()
    ..writeln('// $_header')
    ..writeln()
    ..writeln("import 'dart:ui';")
    ..writeln()
    ..writeln('/// Colour roles. Components name a role, never a value.')
    ..writeln('final class DuePalette {')
    ..writeln('  const DuePalette({')
    ..writeAll(names.map((n) => '    required this.$n,\n'))
    ..writeln('  });')
    ..writeln()
    ..writeAll(names.map((n) => '  final Color $n;\n'))
    ..writeln()
    ..writeln('  static const light = DuePalette(')
    ..writeAll(names.map((n) => '    $n: Color(${_hex(_argb(light[n]!))}),\n'))
    ..writeln('  );')
    ..writeln()
    ..writeln('  static const dark = DuePalette(')
    ..writeAll(names.map((n) => '    $n: Color(${_hex(_argb(dark[n]!))}),\n'))
    ..writeln('  );')
    ..writeln()
    ..writeln('  static DuePalette lerp(DuePalette a, DuePalette b, double t) => DuePalette(')
    ..writeAll(names.map((n) => '    $n: Color.lerp(a.$n, b.$n, t)!,\n'))
    ..writeln('  );')
    ..writeln('}')
    ..writeln();

  void doubles(String cls, String key, String doc) {
    final m = (t[key] as Map).cast<String, num>();
    b
      ..writeln('/// $doc')
      ..writeln('abstract final class $cls {')
      ..writeAll(m.entries.map((e) => '  static const double ${e.key} = ${e.value.toDouble()};\n'))
      ..writeln('}')
      ..writeln();
  }

  doubles('DueRadius', 'radius', 'Corner radii in logical pixels.');
  doubles('DueSize', 'size', 'Type sizes and layout sizes in logical pixels.');

  final motion = (t['motion'] as Map).cast<String, int>();
  b
    ..writeln('/// Motion timings.')
    ..writeln('abstract final class DueMotion {')
    ..writeAll(
      motion.entries.map(
        (e) => '  static const Duration ${e.key.replaceAll('Ms', '')} = Duration(milliseconds: ${e.value});\n',
      ),
    )
    ..writeln('}')
    ..writeln();

  final font = (t['font'] as Map).cast<String, String>();
  b
    ..writeln('/// Bundled font families.')
    ..writeln('abstract final class DueFonts {')
    ..writeAll(font.entries.map((e) => "  static const String ${e.key} = '${e.value}';\n"))
    ..writeln('}');
  return b.toString();
}

String _swift(Map<String, dynamic> t) {
  final color = t['color'] as Map<String, dynamic>;
  final light = (color['light'] as Map).cast<String, String>();
  final dark = (color['dark'] as Map).cast<String, String>();

  String rgba(int v) {
    double c(int shift) => ((v >> shift) & 0xFF) / 255;
    String f(double d) => d.toStringAsFixed(4);
    return 'red: ${f(c(16))}, green: ${f(c(8))}, blue: ${f(c(0))}, alpha: ${f(c(24))}';
  }

  final b = StringBuffer()
    ..writeln('// $_header')
    ..writeln()
    ..writeln('import SwiftUI')
    ..writeln('import UIKit')
    ..writeln()
    ..writeln('private func dynamic(_ light: UIColor, _ dark: UIColor) -> Color {')
    ..writeln('  Color(UIColor { \$0.userInterfaceStyle == .dark ? dark : light })')
    ..writeln('}')
    ..writeln()
    ..writeln('enum DueColor {');
  for (final n in light.keys) {
    b.writeln(
      '  static let $n = dynamic(UIColor(${rgba(_argb(light[n]!))}), '
      'UIColor(${rgba(_argb(dark[n]!))}))',
    );
  }
  b
    ..writeln('}')
    ..writeln()
    ..writeln('enum DueRadius {');
  (t['radius'] as Map).cast<String, num>().forEach((k, v) {
    b.writeln('  static let $k: CGFloat = ${_num(v)}');
  });
  b
    ..writeln('}')
    ..writeln()
    ..writeln('enum DueFont {');
  (t['font'] as Map).cast<String, String>().forEach((k, v) {
    b.writeln('  static let $k = "$v"');
  });
  b.writeln('}');
  return b.toString();
}

bool _sameKeys(Map<String, Object?> a, Map<String, Object?> b) => a.length == b.length && a.keys.every(b.containsKey);
